Workflow.Definition:
"@@ConnectionString: ''
@@Type: 'Local'
@@DesktopType: 'local'
@@DisplayName: 'Computador local'
IMPORT 'controlRepo.appmask' AS appmask
IMPORT 'imageRepo.imgrepo' AS imgrepo
@SENSITIVE: []
SET Repositorio TO $'''C:\\Users\\KLCS00169954\\OneDrive - Klabin\\Power BI - 02-Auxiliares'''
WebAutomation.LaunchChrome.LaunchChrome Url: $'''https://s4prd.sap.klabin.net/sap/bc/ui2/flp?sap-client=400&sap-language=PT#Shell-home''' WindowState: WebAutomation.BrowserWindowState.Minimized ClearCache: False ClearCookies: False WaitForPageToLoadTimeout: 60 Timeout: 60 PiPUserDataFolderMode: WebAutomation.PiPUserDataFolderModeEnum.AutomaticProfile TargetDesktop: $'''{\"DisplayName\":\"Computador local\",\"Route\":{\"ServerType\":\"Local\",\"ServerAddress\":\"\"},\"DesktopType\":\"local\"}''' BrowserInstance=> Browser
WAIT 10
WebAutomation.ExecuteJavascript BrowserInstance: Browser Javascript: $'''function ExecuteScript()
{
 // ============================================================
 // EXTRAÇÃO SAP ODATA
 // POWER AUTOMATE - V13.15.2 - JANELA 3 SEMANAS - SEM PERCENTUAL - CSV UNICO
 //
 // PERÍODO AUTOMÁTICO:
 //
 // DATA_INICIAL:
 // Segunda-feira da semana anterior
 //
 // DATA_FINAL:
 // Domingo da semana anterior
 //
 // V13.11:
 // Restaura o filtro técnico OData da V13.8, que já era estável.
 // NÃO filtra diretamente por OrderOperationStartDateTime no OData.
 //
 // V13.13:
 // Inclui OrderStartDateTime e OrderEndDateTime,
 // confirmados no diagnóstico como datas da linha pai da ordem.
 //
 // NÃO REALIZA DOWNLOAD PELO CHROME.
 //
 // FACT LIMPA:
 // - somente campos reais do OData
 // - nomes originais do OData
 // - sem aliases da planilha MP28
 // - sem colunas auxiliares preenchidas com 0
 // - sem InicioOperacaoDT / FimOperacaoDT
 //
 // Resultado:
 // window.SAP_EXTRACAO_CSV
 //
 // Status:
 // PROCESSANDO
 // CONCLUIDO
 // ERRO
 // ============================================================

 window.SAP_EXTRACAO_CSV = \"\";
 window.SAP_EXTRACAO_STATUS = \"PROCESSANDO\";
 window.SAP_EXTRACAO_ERRO = \"\";
 window.SAP_EXTRACAO_REGISTROS = 0;
 window.SAP_EXTRACAO_DATA_INICIAL = \"\";
 window.SAP_EXTRACAO_DATA_FINAL = \"\";
 window.SAP_EXTRACAO_PAGINA = 0;
 window.SAP_EXTRACAO_PROGRESSO = \"INICIANDO\";

 (async () => {

 try {

 const SAP_CLIENT = \"400\";
 const PAGE_SIZE = 500;
 const MAX_PAGINAS = 200;
 const TIMEOUT_REQUISICAO_MS = 180000;
 const MAX_TEMPO_TOTAL_MS = 5940000;

 const inicioExecucao =
 Date.now();

 function formatarDataBR(data)
 {
 const dia = String(data.getDate()).padStart(2, \"0\");
 const mes = String(data.getMonth() + 1).padStart(2, \"0\");
 const ano = data.getFullYear();

 return `${dia}/${mes}/${ano}`;
 }

 function segundaFeiraSemanaAnterior()
 {
 const hoje =
 new Date();

 const diaSemana =
 hoje.getDay();

 const diasDesdeSegunda =
 diaSemana === 0
 ? 6
 : diaSemana - 1;

 const segundaSemanaAtual =
 new Date(
 hoje.getFullYear(),
 hoje.getMonth(),
 hoje.getDate() - diasDesdeSegunda
 );

 const segundaAnterior =
 new Date(
 segundaSemanaAtual.getFullYear(),
 segundaSemanaAtual.getMonth(),
 segundaSemanaAtual.getDate() - 7
 );

 return formatarDataBR(
 segundaAnterior
 );
 }

 function domingoSemanaAnterior()
 {
 const hoje =
 new Date();

 const diaSemana =
 hoje.getDay();

 const diasDesdeSegunda =
 diaSemana === 0
 ? 6
 : diaSemana - 1;

 const segundaSemanaAtual =
 new Date(
 hoje.getFullYear(),
 hoje.getMonth(),
 hoje.getDate() - diasDesdeSegunda
 );

 const domingoAnterior =
 new Date(
 segundaSemanaAtual.getFullYear(),
 segundaSemanaAtual.getMonth(),
 segundaSemanaAtual.getDate() - 1
 );

 return formatarDataBR(
 domingoAnterior
 );
 }

 // ====================================================
 // JANELA ORIGINAL: SEMANA ANTERIOR + ATUAL + PROXIMA
 // Somente esta janela foi ampliada; preservamos
 // o filtro tecnico OData ja validado nas versoes anteriores.
 // ====================================================
 const SEMANAS_ANTERIORES = 1;
 const SEMANAS_POSTERIORES = 1;

 const hoje = new Date();
 const diaSemanaAtual = hoje.getDay();
 const desdeSegunda = diaSemanaAtual === 0 ? 6 : diaSemanaAtual - 1;
 const segundaAtual = new Date(
 hoje.getFullYear(),
 hoje.getMonth(),
 hoje.getDate() - desdeSegunda
 );
 const inicioPeriodo = new Date(
 segundaAtual.getFullYear(),
 segundaAtual.getMonth(),
 segundaAtual.getDate() - 7 * SEMANAS_ANTERIORES
 );
 const fimPeriodo = new Date(
 segundaAtual.getFullYear(),
 segundaAtual.getMonth(),
 segundaAtual.getDate() + 7 * (SEMANAS_POSTERIORES + 1) - 1
 );

 const DATA_INICIAL = formatarDataBR(inicioPeriodo);
 const DATA_FINAL = formatarDataBR(fimPeriodo);

 // A revisao da ordem e combinada com a data de cada operacao.
 // Ex.: R39, R40 e R41 em uma janela de tres semanas.
 function calcularEventoSemana(data)
 {
 const d = new Date(Date.UTC(
 data.getFullYear(), data.getMonth(), data.getDate()
 ));
 const diaISO = d.getUTCDay() || 7;
 d.setUTCDate(d.getUTCDate() + 4 - diaISO);
 const anoISO = d.getUTCFullYear();
 const primeiroDia = new Date(Date.UTC(anoISO, 0, 1));
 const semanaISO = Math.ceil(((d - primeiroDia) / 86400000 + 1) / 7);
 return \"R\" + semanaISO + \" \" + anoISO;
 }

 const intervalosRevisoes = {};
 const REVISOES_PERMITIDAS = [];
 const totalSemanas = SEMANAS_ANTERIORES + 1 + SEMANAS_POSTERIORES;

 for (let i = 0; i < totalSemanas; i++)
 {
 const inicioSemana = new Date(
 inicioPeriodo.getFullYear(),
 inicioPeriodo.getMonth(),
 inicioPeriodo.getDate() + 7 * i
 );
 const revisao = calcularEventoSemana(inicioSemana);
 const inicioUTC = Date.UTC(
 inicioSemana.getFullYear(),
 inicioSemana.getMonth(),
 inicioSemana.getDate()
 );
 REVISOES_PERMITIDAS.push(revisao);
 intervalosRevisoes[revisao] = {
 inicio: inicioUTC,
 fimExclusivo: inicioUTC + 7 * 86400000
 };
 }

 const FILTRO_REVISOES = \"(\" + REVISOES_PERMITIDAS.map(
 function (revisao) {
 return \"MaintenanceRevision eq \'\" +
 revisao.replace(/\'/g, \"\'\'\") + \"\'\";
 }
 ).join(\" or \") + \")\";

 window.SAP_EXTRACAO_EVENTO = REVISOES_PERMITIDAS.join(\" | \");
 window.SAP_EXTRACAO_EVENTOS = REVISOES_PERMITIDAS.slice();
 window.SAP_EXTRACAO_STATUS_PROCESSAMENTO = 30;

 window.SAP_EXTRACAO_DATA_INICIAL =
 DATA_INICIAL;

 window.SAP_EXTRACAO_DATA_FINAL =
 DATA_FINAL;

 console.log(\"========================================\");
 console.log(\"PERÍODO AUTOMÁTICO - ANTERIOR + ATUAL + PRÓXIMA\");
 console.log(`DATA_INICIAL: ${DATA_INICIAL}`);
 console.log(`DATA_FINAL: ${DATA_FINAL}`);
 console.log(`Revisoes da janela: ${REVISOES_PERMITIDAS.join(\" | \")}`);
 console.log(\"========================================\");

 const baseUrl =
 `/sap/opu/odata/sap/` +
 `RSH_EAM_ORDER_GANTT_SRV/` +
 `C_RSHOrdersAndOperations`;

 function dataParaSAP(
 dataBR,
 adicionarDias = 0
 )
 {
 const partes =
 dataBR
 .split(\"/\")
 .map(Number);

 if (
 partes.length !== 3 ||
 partes.some(Number.isNaN)
 )
 {
 throw new Error(
 `Data inválida: ${dataBR}. Use DD/MM/AAAA.`
 );
 }

 const [dia, mes, ano] = partes;

 const data =
 new Date(
 Date.UTC(
 ano,
 mes - 1,
 dia + adicionarDias
 )
 );

 const yyyy = data.getUTCFullYear();

 const mm =
 String(
 data.getUTCMonth() + 1
 ).padStart(2, \"0\");

 const dd =
 String(
 data.getUTCDate()
 ).padStart(2, \"0\");

 return `${yyyy}-${mm}-${dd}T03:00:00`;
 }

 const inicioSAP =
 dataParaSAP(DATA_INICIAL);

 const fimSAP =
 dataParaSAP(DATA_FINAL, 1);

 const camposOData = [

 \"MaintenanceOrder\",
 \"MaintenanceOrderDesc\",
 \"MaintenanceOrderOperation\",
 \"OperationDescription\",

 \"MaintenancePlannerGroup\",
 \"MainWorkCenter\",
 \"WorkCenter\",

 \"FunctionalLocation\",
 \"FunctionalLocationName\",

 \"WBSElement\",
 \"WBSDescription\",
 \"Project\",
 \"ProjectDescription\",

 \"OperationDuration\",
 \"OperationDurationUnit\",

 \"OperationPlannedWork\",
 \"OperationPlannedWorkUnit\",

 \"OrderOperationStartDateTime\",
 \"OrderOperationEndDateTime\",

 // Datas reais da ORDEM pai exibidas no SAP
 \"OrderStartDateTime\",
 \"OrderEndDateTime\",

 \"OperationPersonResponsible\",
 \"OperationPersonRespName\",
 \"AssignedPerson\",

 \"MaintPriorityDesc\",
 \"ProcessingStatus\",
 \"ProcessingStatusText\",
 \"MaintenanceRevision\",
 \"NumberOfCapacities\"
 ];

 const select =
 camposOData.join(\",\");

 const filtro =

 `OrderOperationRowLevel eq 0 and ` +
 `ProcessingStatus eq 30 and ` +
 `${FILTRO_REVISOES} and (` +

 `(` +

 `SchedulingIsPerformedBackward eq \' \' and ` +

 `(` +

 `OpErlstSchedldExecEndDte gt datetime\'${inicioSAP}\' ` +

 `or (` +

 `OpErlstSchedldExecEndDte eq datetime\'${inicioSAP}\' ` +

 `and ` +

 `OpErlstSchedldExecEndTme gt time\'PT00H00M00S\'` +

 `)` +

 `) ` +

 `and ` +

 `OpErlstSchedldExecStrtDte lt datetime\'${fimSAP}\'` +

 `)` +

 ` or ` +

 `(` +

 `SchedulingIsPerformedBackward eq \'X\' and ` +

 `(` +

 `OpLtstSchedldExecEndDte gt datetime\'${inicioSAP}\' ` +

 `or (` +

 `OpLtstSchedldExecEndDte eq datetime\'${inicioSAP}\' ` +

 `and ` +

 `OpLtstSchedldExecEndTme gt time\'PT00H00M00S\'` +

 `)` +

 `) ` +

 `and ` +

 `OpLtstSchedldExecStrtDte lt datetime\'${fimSAP}\'` +

 `)` +

 `)`;

 window.SAP_EXTRACAO_FILTRO = filtro;

 let skip = 0;
 let paginaAtual = 0;
 let todosRegistros = [];
 const assinaturasPaginas = new Set();

 function assinaturaPagina(registros)
 {
 if (
 !registros ||
 registros.length === 0
 )
 {
 return \"VAZIA\";
 }

 const chave = (r) =>
 [
 r.MaintenanceOrder || \"\",
 r.MaintenanceOrderOperation || \"\",
 r.WorkCenter || \"\",
 r.FunctionalLocation || \"\"
 ].join(\"|\");

 const primeira =
 chave(registros[0]);

 const ultima =
 chave(
 registros[
 registros.length - 1
 ]
 );

 return (
 `${registros.length}::` +
 `${primeira}::${ultima}`
 );
 }

 async function fetchComTimeout(
 url,
 options,
 timeoutMs
 )
 {
 const controller =
 new AbortController();

 const timeoutId =
 setTimeout(
 () => controller.abort(),
 timeoutMs
 );

 try
 {
 return await fetch(
 url,
 {
 ...options,
 signal: controller.signal
 }
 );
 }
 catch (erro)
 {
 if (
 erro &&
 erro.name === \"AbortError\"
 )
 {
 throw new Error(
 `Timeout de ${timeoutMs / 1000} segundos na requisição OData.`
 );
 }

 throw erro;
 }
 finally
 {
 clearTimeout(
 timeoutId
 );
 }
 }

 console.log(\"========================================\");
 console.log(\"EXTRAÇÃO SAP - POWER AUTOMATE V13.15.2 | ESCALONADO + REVISOES\");
 console.log(\"FACT LIMPA - FILTRO ODATA ESTÁVEL RESTAURADO\");
 console.log(\"========================================\");
 console.log(`Período: ${DATA_INICIAL} a ${DATA_FINAL}`);
 console.log(`Revisoes selecionadas: ${REVISOES_PERMITIDAS.join(\" | \")}`);
 console.log(\"ProcessingStatus: 30 (Escalonado)\");
 console.log(`Campos OData: ${camposOData.length}`);

 while (true)
 {
 paginaAtual += 1;

 if (
 paginaAtual > MAX_PAGINAS
 )
 {
 throw new Error(
 `Limite de ${MAX_PAGINAS} páginas atingido. ` +
 `A extração foi interrompida por segurança.`
 );
 }

 if (
 Date.now() - inicioExecucao >
 MAX_TEMPO_TOTAL_MS
 )
 {
 throw new Error(
 \"Tempo máximo total de 99 minutos atingido. \" +
 \"A extração foi interrompida por segurança.\"
 );
 }

 window.SAP_EXTRACAO_PAGINA =
 paginaAtual;

 window.SAP_EXTRACAO_PROGRESSO =
 `Página ${paginaAtual} | ` +
 `Registros ${todosRegistros.length}`;

 const url =

 `${baseUrl}` +

 `?sap-client=${SAP_CLIENT}` +

 `&$filter=${encodeURIComponent(filtro)}` +

 `&$select=${encodeURIComponent(select)}` +

 `&$orderby=${encodeURIComponent(
 \"MaintenanceOrder asc,\" +
 \"MaintenanceOrderOperation asc\"
 )}` +

 `&$top=${PAGE_SIZE}` +

 `&$skip=${skip}` +

 `&$format=json`;

 console.log(
 `Página ${paginaAtual} | ` +
 `Buscando ${skip + 1} a ${skip + PAGE_SIZE}`
 );

 const response =
 await fetchComTimeout(
 url,
 {
 method: \"GET\",
 credentials: \"include\",
 headers:
 {
 \"Accept\":
 \"application/json\",

 \"DataServiceVersion\":
 \"2.0\",

 \"MaxDataServiceVersion\":
 \"2.0\",

 \"X-Requested-With\":
 \"XMLHttpRequest\"
 }
 },
 TIMEOUT_REQUISICAO_MS
 );

 console.log(
 `HTTP ${response.status}`
 );

 if (!response.ok)
 {
 const erroSAP =
 await response.text();

 console.error(
 \"ERRO SAP:\"
 );

 console.error(
 erroSAP
 );

 throw new Error(
 `HTTP ${response.status} - ` +
 `${response.statusText}`
 );
 }

 const json =
 await response.json();

 const registros =
 json?.d?.results || [];

 const assinatura =
 assinaturaPagina(
 registros
 );

 if (
 registros.length > 0 &&
 assinaturasPaginas.has(
 assinatura
 )
 )
 {
 throw new Error(
 \"O SAP devolveu uma página já recebida anteriormente. \" +
 \"Possível repetição de paginação detectada.\"
 );
 }

 if (
 registros.length > 0
 )
 {
 assinaturasPaginas.add(
 assinatura
 );
 }

 todosRegistros.push(
 ...registros
 );

 window.SAP_EXTRACAO_REGISTROS =
 todosRegistros.length;

 window.SAP_EXTRACAO_PROGRESSO =
 `Página ${paginaAtual} concluída | ` +
 `Total ${todosRegistros.length}`;

 console.log(
 `${registros.length} recebidos | ` +
 `Total: ${todosRegistros.length}`
 );

 if (
 registros.length < PAGE_SIZE
 )
 {
 break;
 }

 skip += PAGE_SIZE;
 }

 // ====================================================
 // VALIDACAO POR OPERACAO / SEMANA DA REVISAO
 // Limites: segunda 00:00 inclusiva; segunda seguinte exclusiva.
 // Nao usa a data da ordem pai.
 // ====================================================
 function diaLocalEmUTC(valor)
 {
 if (valor === null || valor === undefined || valor === \"\")
 return null;

 let data;
 if (typeof valor === \"string\" && /^\\/Date\\((-?\\d+)(?:[+-]\\d+)?\\)\\/$/.test(valor))
 {
 data = new Date(Number(valor.match(/^\\/Date\\((-?\\d+)/)[1]));
 }
 else if (typeof valor === \"string\" && /^\\d{2}\\/\\d{2}\\/\\d{4}/.test(valor))
 {
 const partes = valor.slice(0, 10).split(\"/\").map(Number);
 return Date.UTC(partes[2], partes[1] - 1, partes[0]);
 }
 else
 {
 data = new Date(valor);
 }

 if (Number.isNaN(data.getTime())) return null;
 return Date.UTC(data.getFullYear(), data.getMonth(), data.getDate());
 }

 const totalRecebido = todosRegistros.length;
 const motivosExclusao = { semRevisao: 0, semData: 0, foraRevisao: 0 };
 const contagemPorRevisao = {};
 for (let i = 0; i < REVISOES_PERMITIDAS.length; i++)
 {
 contagemPorRevisao[REVISOES_PERMITIDAS[i]] = 0;
 }

 const registrosValidados = [];
 for (let i = 0; i < todosRegistros.length; i++)
 {
 const registro = todosRegistros[i];
 const revisao = String(registro.MaintenanceRevision || \"\").trim();
 const intervalo = intervalosRevisoes[revisao];
 if (!intervalo)
 {
 motivosExclusao.semRevisao++;
 continue;
 }

 const diaOperacao = diaLocalEmUTC(registro.OrderOperationStartDateTime);
 if (diaOperacao === null)
 {
 motivosExclusao.semData++;
 continue;
 }

 if (diaOperacao < intervalo.inicio || diaOperacao >= intervalo.fimExclusivo)
 {
 motivosExclusao.foraRevisao++;
 continue;
 }

 contagemPorRevisao[revisao]++;
 registrosValidados.push(registro);
 }
 todosRegistros = registrosValidados;

 window.SAP_EXTRACAO_REGISTROS = todosRegistros.length;
 window.SAP_EXTRACAO_CONTAGEM_REVISOES = contagemPorRevisao;
 window.SAP_EXTRACAO_EXCLUSOES = motivosExclusao;
 console.log(`Recebidos: ${totalRecebido} | Validados: ${todosRegistros.length}`);
 console.table(contagemPorRevisao);
 console.log(\"Exclusoes por revisao:\", motivosExclusao);

 // ====================================================
 // FACT LIMPA
 //
 // Não criamos aliases ou colunas derivadas aqui.
 // O CSV preserva exatamente os nomes dos campos OData
 // definidos em camposOData.
 //
 // Valores nulos permanecem vazios.
 // ====================================================

 function tratarValor(valor)
 {
 if (
 valor === null ||
 valor === undefined
 )
 {
 return \"\";
 }

 if (
 typeof valor === \"string\" &&
 /^\\/Date\\((-?\\d+)(?:[+-]\\d+)?\\)\\/$/.test(valor)
 )
 {
 const match =
 valor.match(
 /^\\/Date\\((-?\\d+)/
 );

 const timestamp =
 Number(
 match[1]
 );

 const data =
 new Date(timestamp);

 const dia =
 String(
 data.getDate()
 ).padStart(2, \"0\");

 const mes =
 String(
 data.getMonth() + 1
 ).padStart(2, \"0\");

 const ano =
 data.getFullYear();

 const hora =
 String(
 data.getHours()
 ).padStart(2, \"0\");

 const minuto =
 String(
 data.getMinutes()
 ).padStart(2, \"0\");

 const segundo =
 String(
 data.getSeconds()
 ).padStart(2, \"0\");

 return (
 `${dia}/${mes}/${ano} ` +
 `${hora}:${minuto}:${segundo}`
 );
 }

 if (
 typeof valor === \"object\"
 )
 {
 return JSON.stringify(valor);
 }

 return String(valor);
 }

 function escaparCSV(valor)
 {
 const texto =
 tratarValor(valor);

 return (
 `\"${texto.replace(/\"/g, \'\"\"\')}\"`
 );
 }

 // Sempre preserva o cabeçalho do CSV, mesmo com zero registros.
 // Assim o Power BI mantém o schema da FactOrdersOperations.
 const colunasCSV =
 [...camposOData];

 // ====================================================
 // CSV ÚNICO
 //
 // A extração é montada integralmente na memória do Chrome.
 // O Power Automate lê o CSV uma única vez e grava o arquivo
 // em uma única operação no repositório.
 // ====================================================

 const linhas =
 [];

 linhas.push(
 colunasCSV
 .map(
 escaparCSV
 )
 .join(\";\")
 );

 for (
 const registro
 of todosRegistros
 )
 {
 linhas.push(
 colunasCSV
 .map(
 coluna =>
 escaparCSV(
 registro[coluna]
 )
 )
 .join(\";\")
 );
 }

 const csv =
 \"\\uFEFF\" +
 linhas.join(
 \"\\r\\n\"
 );

 if (todosRegistros.length === 0)
 {
 console.warn(
 \"Nenhum registro retornado pelo filtro OData estável. \" +
 \"O CSV será gravado somente com o cabeçalho.\"
 );
 }

 window.SAP_EXTRACAO_CSV =
 csv;

 window.SAP_EXTRACAO_REGISTROS =
 todosRegistros.length;

 window.SAP_EXTRACAO_STATUS =
 \"CONCLUIDO\";

 window.SAP_EXTRACAO_PROGRESSO =
 \"CONCLUIDO\";

 console.log(\"========================================\");
 console.log(\"EXTRAÇÃO CONCLUÍDA\");
 console.log(`Período: ${DATA_INICIAL} a ${DATA_FINAL}`);
 console.log(`Registros: ${todosRegistros.length}`);
 console.log(`Colunas: ${colunasCSV.length}`);
 console.log(`Tamanho CSV: ${csv.length} caracteres`);
 console.log(\"CSV pronto para leitura única pelo Power Automate.\");
 console.log(\"========================================\");

 }
 catch (erro)
 {
 console.error(
 \"ERRO NA EXTRAÇÃO:\"
 );

 console.error(
 erro
 );

 window.SAP_EXTRACAO_STATUS =
 \"ERRO\";

 window.SAP_EXTRACAO_PROGRESSO =
 \"ERRO\";

 window.SAP_EXTRACAO_ERRO =
 erro?.message ||
 String(erro);

 window.SAP_EXTRACAO_CSV =
 \"\";
 }

 })();

 return \"EXTRACAO_INICIADA\";
}
''' Result=> Result
WAIT 2
WebAutomation.ExecuteJavascript BrowserInstance: Browser Javascript: $'''function ExecuteScript()
{
 return window.SAP_EXTRACAO_STATUS || \"PROCESSANDO\";
}''' Result=> StatusExtracao
WAIT 2
LOOP WHILE (StatusExtracao) = ($'''PROCESSANDO''')
 WAIT 2
 WebAutomation.ExecuteJavascript BrowserInstance: Browser Javascript: $'''function ExecuteScript()

{

 return window.SAP_EXTRACAO_STATUS || \"PROCESSANDO\";

}''' Result=> StatusExtracao
END
WebAutomation.ExecuteJavascript BrowserInstance: Browser Javascript: $'''function ExecuteScript()
{
 return window.SAP_EXTRACAO_CSV || \"\";
}
''' Result=> CsvSAP
File.WriteText File: $'''%Repositorio%\\SAP_Ordens_Manutencao.csv''' TextToWrite: CsvSAP AppendNewLine: False IfFileExists: File.IfFileExists.Overwrite Encoding: File.FileEncoding.UTF8
"
